package hyperliquid

import (
	"encoding/json"
	"os"
	"testing"

	"github.com/ethereum/go-ethereum/common"
	"github.com/ethereum/go-ethereum/common/hexutil"
	"github.com/ethereum/go-ethereum/signer/core/apitypes"
	"github.com/shopspring/decimal"

	"github.com/alphafoxai/alphafox-hedge-trader/pkg/evmsign"
)

// testdata/l1_golden.json is generated by hyperliquid-python-sdk 0.24.0
// sign_l1_action with the SDK's public test key; see docs/golden-vectors.md.
type goldenFile struct {
	PrivateKey string `json:"privateKey"`
	Address    string `json:"address"`
	Cases      []struct {
		Name         string            `json:"name"`
		Mainnet      bool              `json:"mainnet"`
		VaultAddress *string           `json:"vaultAddress"`
		ExpiresAfter *uint64           `json:"expiresAfter"`
		Nonce        uint64            `json:"nonce"`
		ActionHash   string            `json:"actionHash"`
		Signature    evmsign.Signature `json:"signature"`
	} `json:"cases"`
}

func goldenActions(t *testing.T) map[string]any {
	t.Helper()
	ioc := OrderWire{Asset: 0, IsBuy: true, Price: "62345", Size: "0.0123", Type: OrderTypeWire{Limit: &LimitWire{TIF: "Ioc"}}}
	gtc := OrderWire{Asset: 1, IsBuy: false, Price: "2400.5", Size: "1.5", ReduceOnly: true,
		Type: OrderTypeWire{Limit: &LimitWire{TIF: "Gtc"}}, Cloid: "0x00000000000000000000000000000001"}
	return map[string]any{
		"order_ioc":           NewOrderAction([]OrderWire{ioc}, nil),
		"order_cloid_builder": NewOrderAction([]OrderWire{gtc}, &BuilderWire{B: "0xf945417968b53adc1e0489e5a287d2e41c8b3d79", F: 50}),
		"cancel":              NewCancelAction([]CancelWire{{Asset: 0, Oid: 123456789}}),
		"update_leverage":     NewUpdateLeverageAction(1, false, 20),
		"order_vault_expires": NewOrderAction([]OrderWire{ioc}, nil),
	}
}

func TestL1ActionMatchesOfficialSDK(t *testing.T) {
	raw, err := os.ReadFile("testdata/l1_golden.json")
	if err != nil {
		t.Fatal(err)
	}
	var golden goldenFile
	if err := json.Unmarshal(raw, &golden); err != nil {
		t.Fatal(err)
	}
	signer, err := evmsign.NewLocalSigner(golden.PrivateKey)
	if err != nil {
		t.Fatal(err)
	}
	actions := goldenActions(t)
	for _, c := range golden.Cases {
		network := Testnet
		if c.Mainnet {
			network = Mainnet
		}
		p := L1Params{Nonce: c.Nonce, ExpiresAfter: c.ExpiresAfter}
		if c.VaultAddress != nil {
			vault := common.HexToAddress(*c.VaultAddress)
			p.VaultAddress = &vault
		}
		hash, err := ActionHash(actions[c.Name], p)
		if err != nil {
			t.Fatalf("%s: %v", c.Name, err)
		}
		if got := hexutil.Encode(hash); got != c.ActionHash {
			t.Fatalf("%s mainnet=%v: action hash %s, want %s", c.Name, c.Mainnet, got, c.ActionHash)
		}
		sig, err := SignL1Action(signer, actions[c.Name], p, network)
		if err != nil {
			t.Fatal(err)
		}
		// The SDK emits r/s without zero padding; compare as integers.
		if hexutil.MustDecodeBig(sig.R).Cmp(hexutil.MustDecodeBig(c.Signature.R)) != 0 ||
			hexutil.MustDecodeBig(sig.S).Cmp(hexutil.MustDecodeBig(c.Signature.S)) != 0 || sig.V != c.Signature.V {
			t.Fatalf("%s mainnet=%v: signature %+v, want %+v", c.Name, c.Mainnet, sig, c.Signature)
		}
		digest, _, err := apitypes.TypedDataAndHash(L1TypedData(hash, network))
		if err != nil {
			t.Fatal(err)
		}
		if addr, err := evmsign.RecoverAddress(digest, sig); err != nil || addr != common.HexToAddress(golden.Address) {
			t.Fatalf("%s: recovered %s (%v), want %s", c.Name, addr, err, golden.Address)
		}
	}
}

func TestRoundPerpPriceMatchesSDK(t *testing.T) {
	raw, err := os.ReadFile("testdata/px_golden.json")
	if err != nil {
		t.Fatal(err)
	}
	var cases []struct {
		Px         string `json:"px"`
		SzDecimals int    `json:"szDecimals"`
		Want       string `json:"want"`
	}
	if err := json.Unmarshal(raw, &cases); err != nil {
		t.Fatal(err)
	}
	for _, c := range cases {
		got := RoundPerpPrice(decimal.RequireFromString(c.Px), c.SzDecimals)
		if !got.Equal(decimal.RequireFromString(c.Want)) {
			t.Errorf("RoundPerpPrice(%s, %d) = %s, want %s", c.Px, c.SzDecimals, got, c.Want)
		}
	}
}

func TestFloatToWire(t *testing.T) {
	for in, want := range map[string]string{"62345.000": "62345", "0.01230": "0.0123", "-0": "0", "100": "100", "1e3": "1000"} {
		got, err := FloatToWire(decimal.RequireFromString(in))
		if err != nil || got != want {
			t.Errorf("FloatToWire(%s) = %q, %v; want %q", in, got, err, want)
		}
	}
	if _, err := FloatToWire(decimal.RequireFromString("0.123456789")); err == nil {
		t.Error("expected an error for 9 decimals")
	}
}
